e reizen. Onderweg sluit hij zich aan bij reisgenoten met verschillende achtergronden en belangen. Hun gezamenlijke opdracht lijkt eenvoudig te omschrijven, maar vraagt steeds meer vertrouwen en moed zodra de dreiging buiten de Gouw tastbaar wordt.","source_type":"official_catalog","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/1566929/de-reisgenoten.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T11:04:00Z","review_batch":"nl005-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/1566929/de-reisgenoten.html","checkedAt":"2026-11-01","fact":"Source content actually read; original Dutch synopsis, identity reviewed separately","sha256":"d3e927124b55f240032dda0b40926a9337590892d98736daca5b8564673bcbb9"}]}},{"relation":"editions","ref":"edition:9789020554083","key":{"id":976200118},"before":null,"after":{"work_id":924100222,"title":"Iron Flame","isbn_13":"9789020554083","isbn_10":null,"language":"nld","publisher":"VBK Media","open_library_edition_id":null,"id":976200118}},{"relation":"catalog_edition_metadata","ref":"metadata:9789020554083","key":{"edition_id":"@edition:9789020554083"},"before":null,"after":{"edition_id":"@edition:9789020554083","work_id":924100222,"bound_author_id":924300152,"bound_title":"Iron Flame","bound_language":"nld","bound_isbn13":"9789020554083","format":"hardcover","cover_url":"https://metadata.isbn.nl/ie_fcache/0000615516_Een_ijzeren_vlam_limited_edition_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/1766688/een-ijzeren-vlam-limited-edition.html","review_status":"approved","reviewed_at":"2026-11-01T11:04:00Z","review_batch":"nl005-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/1766688/een-ijzeren-vlam-limited-edition.html","checkedAt":"2026-11-01","sha256":"d0e078b1c7fa99a786ae2678ce1615513ef3ed3017928aa1d30486ed9d2d67b8","fact":"Exact title/author/ISBN, physical format and language source reviewed; independent contradictions recorded"},{"url":"https://metadata.isbn.nl/ie_fcache/0000615516_Een_ijzeren_vlam_limited_edition_0_0.jpg","checkedAt":"2026-11-01T10:56:55.126Z","sha256":"10f027efb6cc1a54fc2799f1f6639fb6bc7c7b6bdea29457911a2d4f2ca8873a","bytes":1065730,"fact":"Same-edition source association and title/author artwork visually reviewed; not only HTTP200"}]}},{"relation":"catalog_work_descriptions","ref":"description:222","key":{"work_id":924100222,"language":"nl"},"before":null,"after":{"work_id":924100222,"language":"nl","bound_author_id":924300152,"text":"Violet heeft haar eerste jaar aan het Basgiath Oorlogscollege overleefd, maar haar opleiding wordt er niet veiliger op. Een nieuwe vicecommandant stelt haar loyaliteit op de proef en probeert haar onder druk te zetten om iemand van wie zij houdt te verraden. Intussen vermoedt Violet dat het college belangrijke zaken verborgen houdt. Ze moet kiezen hoe ver zij durft te gaan om de waarheid te achterhalen zonder zichzelf en anderen prijs te geven.","source_type":"official_catalog","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/1766688/een-ijzeren-vlam-limited-edition.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T11:04:00Z","review_batch":"nl005-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/1766688/een-ijzeren-vlam-limited-edition.html","checkedAt":"2026-11-01","fact":"Source content actually read; original Dutch synopsis, identity reviewed separately","sha256":"d0e078b1c7fa99a786ae2678ce1615513ef3ed3017928aa1d30486ed9d2d67b8"}]}},{"relation":"editions","ref":"edition:9789020554113","key":{"id":976200119},"before":null,"after":{"work_id":924100226,"title":"Onyx Storm","isbn_13":"9789020554113","isbn_10":null,"language":"nld","publisher":"VBK Media","open_library_edition_id":null,"id":976200119}},{"relation":"catalog_edition_metadata","ref":"metadata: