57,"text":"Darrow werkt diep onder het oppervlak van Mars en gelooft dat hij daarmee de planeet geschikt maakt voor toekomstige bewoners. Als Rode behoort hij tot de laagste groep in een samenleving die mensen naar kleur indeelt. Wanneer hij ontdekt dat boven hem al lang een bewoonde wereld bestaat, verandert de betekenis van zijn werk en offers. Zijn zoektocht naar rechtvaardigheid brengt hem tegenover de machthebbers van die maatschappij te staan.","source_type":"official_catalog","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/771701/rood.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T11:04:00Z","review_batch":"nl005-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/771701/rood.html","checkedAt":"2026-11-01","fact":"Source content actually read; original Dutch synopsis, identity reviewed separately","sha256":"625215df8019ec88100a65a23e6070a1e603ad6ce2c58b16ad01873cc23ab399"}]}},{"relation":"editions","ref":"edition:9789000376360","key":{"id":976200121},"before":null,"after":{"work_id":924100253,"title":"Hof van zilveren vlammen","isbn_13":"9789000376360","isbn_10":null,"language":"nld","publisher":"Uitgeverij Unieboek | Het Spectrum","open_library_edition_id":null,"id":976200121}},{"relation":"catalog_edition_metadata","ref":"metadata:9789000376360","key":{"edition_id":"@edition:9789000376360"},"before":null,"after":{"edition_id":"@edition:9789000376360","work_id":924100253,"bound_author_id":924300125,"bound_title":"Hof van zilveren vlammen","bound_language":"nld","bound_isbn13":"9789000376360","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/0000513547_Hof_van_zilveren_vlammen_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/1398801/hof-van-zilveren-vlammen.html","review_status":"approved","reviewed_at":"2026-11-01T11:04:00Z","review_batch":"nl005-03-20261101","evidence":[{"url":"https://me