derzoek maakt afstand houden moeilijk. Terwijl hij probeert te begrijpen wat het meisje is overkomen, groeit zijn twijfel over de mogelijke samenhang met zijn eigen onopgehelderde verleden.","source_type":"official_catalog","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/463579/de-offerplaats.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T11:04:00Z","review_batch":"nl005-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/463579/de-offerplaats.html","checkedAt":"2026-11-01","fact":"Source content actually read; original Dutch synopsis, identity reviewed separately","sha256":"ffc0d02d62668541797f3529b58cf05ff2ca2023e8376fe5017616e0d2098125"}]}},{"relation":"editions","ref":"edition:9789044621853","key":{"id":976200125},"before":null,"after":{"work_id":924100673,"title":"Vijftig tinten donkerder","isbn_13":"9789044621853","isbn_10":null,"language":"nld","publisher":"Prometheus, Uitgeverij","open_library_edition_id":null,"id":976200125}},{"relation":"catalog_edition_metadata","ref":"metadata:9789044621853","key":{"edition_id":"@edition:9789044621853"},"before":null,"after":{"edition_id":"@edition:9789044621853","work_id":924100673,"bound_author_id":924300397,"bound_title":"Vijftig tinten donkerder","bound_language":"nld","bound_isbn13":"9789044621853","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/0000015516_Vijftig_tinten_donkerder_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/77043/vijftig-tinten-donkerder.html","review_status":"approved","reviewed_at":"2026-11-01T11:04:00Z","review_batch":"nl005-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/77043/vijftig-tinten-donkerder.html","checkedAt":"2026-11-01","sha256":"ef61742285d78103ba62a79d60bc29d756904bf8ccaa71419788a6b19526984e","fact":"Exact title/author/ISBN, physical format and language source reviewed; independent contradictions recorded"},{"url":"https://metadata.isbn.nl/ie_fcache/0000015516_Vijftig_tinten_donkerder_0_0.jpg","checkedAt":"2026-11-01T10:57:06.166Z","sha256":"75e4b4f65a9afbbd16fe9e632d08ce9f1048b4aa54514d1f949b7195869dadf6","bytes":97514,"fact":"Same-edition source association and title/author artwork visually reviewed; not only HTTP200"}]}},{"relation":"catalog_work_descriptions","ref":"description:673","key":{"work_id":924100673,"language":"nl"},"before":null,"after":{"work_id":924100673,"language":"nl","bound_author_id":924300397,"text":"Anastasia Steele heeft haar verhouding met Christian Grey verbroken en probeert een eigen bestaan op te bouwen. Haar gevoelens voor hem verdwijnen daarmee niet. Wanneer hij opnieuw toenadering zoekt, moet ze bepalen onder welke voorwaarden zij hem kan vertrouwen. Ze ontdekt meer over zijn verleden en over relaties die nog altijd op hun leven inwerken. Hun poging opnieuw te beginnen brengt zo ook de grenzen en ongelijkheid tussen hen terug.","source_type":"official_catalog","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/77043/vijftig-tinten-donkerder.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T11:04:00Z","review_batch":"nl005-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/77043/vijftig-tinten-donkerder.html","checkedAt":"2026-11-01","fact":"Source content actually read; original Dutch synopsis, identity reviewed separately","sha256":"ef61742285d78103ba62a79d60bc29d756904bf8ccaa71419788a6b19526984e"}]}},{"relation":"editions","ref":"edition:9789020552010","key":{"id":976200126},"before":null,"after":{"work_id":924100675,"title":"Things we never got over","isbn_13":"9789020552010","isbn_10":null,"language":"nld","publisher":"VBK Media","open_library_edition_id":null,"id":976200126}},{"relation":"catalog_edition_metadata","ref":"metadata:9789020552010","key":{"edition_id":"@edition:9789020552010"},"before"